import React, { useEffect, useMemo, useState } from 'react';
import api from '@/lib/api';

const SEMAFOROS = ['', 'VERDE', 'AMARILLO', 'ROJO'];
const PRIORIDADES = ['BAJA', 'MEDIA', 'ALTA', 'CRITICA'];

const card = { border: '1px solid #e5e7eb', borderRadius: 12, padding: 16, background: '#fff' };
const input = { width: '100%', border: '1px solid #d1d5db', borderRadius: 8, padding: '8px 10px' };
const button = { border: '1px solid #111827', borderRadius: 8, padding: '8px 12px', background: '#111827', color: '#fff', fontWeight: 600, cursor: 'pointer' };
const secondary = { ...button, background: '#fff', color: '#111827' };

function money(value) {
  const number = Number(value || 0);
  return number.toLocaleString('es-MX', { style: 'currency', currency: 'MXN' });
}

function number(value, decimals = 2) {
  if (value === null || value === undefined || value === '') return '-';
  const parsed = Number(value);
  if (Number.isNaN(parsed)) return '-';
  return parsed.toLocaleString('es-MX', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
}

function date(value) {
  if (!value) return '-';
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? String(value) : parsed.toLocaleDateString('es-MX');
}

function badgeStyle(value) {
  const normalized = String(value || '').toUpperCase();
  if (normalized === 'ROJO') return { background: '#fee2e2', color: '#991b1b' };
  if (normalized === 'AMARILLO') return { background: '#fef3c7', color: '#92400e' };
  if (normalized === 'VERDE') return { background: '#dcfce7', color: '#166534' };
  return { background: '#f3f4f6', color: '#374151' };
}

function SemaforoBadge({ value }) {
  return (
    <span style={{ ...badgeStyle(value), borderRadius: 999, padding: '3px 8px', fontSize: 12, fontWeight: 700 }}>
      {value || 'SIN_DATOS'}
    </span>
  );
}

export default function LotesProveedorPage() {
  const [rows, setRows] = useState([]);
  const [claims, setClaims] = useState([]);
  const [totalRows, setTotalRows] = useState(0);
  const [filters, setFilters] = useState({ lote: '', proveedor_id: '', semaforo: '' });
  const [selectedRow, setSelectedRow] = useState(null);
  const [drilldown, setDrilldown] = useState(null);
  const [claimForm, setClaimForm] = useState({ motivo: '', descripcion: '', prioridad: 'MEDIA' });
  const [loading, setLoading] = useState(false);
  const [detailLoading, setDetailLoading] = useState(false);
  const [claimSubmitting, setClaimSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const kpis = useMemo(function calculateKpis() {
    const impacto = rows.reduce(function sum(acc, row) { return acc + Number(row.ImpactoEconomico || 0); }, 0);
    const rojos = rows.filter(function isRed(row) { return String(row.Semaforo || '').toUpperCase() === 'ROJO'; }).length;
    const amarillos = rows.filter(function isYellow(row) { return String(row.Semaforo || '').toUpperCase() === 'AMARILLO'; }).length;
    const reclamosAbiertos = claims.filter(function isOpen(claim) { return String(claim.Estatus || '').toUpperCase() === 'ABIERTO'; }).length;
    return { impacto, rojos, amarillos, reclamosAbiertos };
  }, [rows, claims]);

  function updateFilter(field, value) {
    setFilters(function next(current) { return { ...current, [field]: value }; });
  }

  function buildRendimientosUrl() {
    const query = new URLSearchParams();
    query.set('limit', '100');
    query.set('offset', '0');
    if (filters.lote.trim()) query.set('lote', filters.lote.trim());
    if (filters.proveedor_id.trim()) query.set('proveedor_id', filters.proveedor_id.trim());
    if (filters.semaforo) query.set('semaforo', filters.semaforo);
    return '/tablajeria/lotes-proveedor/rendimientos?' + query.toString();
  }

  async function loadData() {
    setLoading(true);
    setError('');
    setNotice('');
    try {
      const lotesRes = await api.get(buildRendimientosUrl());
      const reclamosRes = await api.get('/tablajeria/reclamos-proveedor?limit=100');
      const nextRows = lotesRes.data && lotesRes.data.rendimientos ? lotesRes.data.rendimientos : [];
      const nextClaims = reclamosRes.data && reclamosRes.data.reclamos ? reclamosRes.data.reclamos : [];
      setRows(nextRows);
      setClaims(nextClaims);
      setTotalRows(lotesRes.data && lotesRes.data.total ? lotesRes.data.total : nextRows.length);
    } catch (err) {
      setError('No fue posible cargar lotes proveedor. Valida conexión y permisos.');
    } finally {
      setLoading(false);
    }
  }

  async function loadDrilldown(row) {
    if (!row || !row.LoteRendimientoID) {
      setError('El lote seleccionado no tiene identificador.');
      return;
    }
    setSelectedRow(row);
    setDrilldown(null);
    setDetailLoading(true);
    setError('');
    setNotice('');
    try {
      const response = await api.get('/tablajeria/lotes-proveedor/' + row.LoteRendimientoID + '/drilldown');
      setDrilldown(response.data || null);
    } catch (err) {
      setError('No fue posible cargar el detalle del lote proveedor.');
    } finally {
      setDetailLoading(false);
    }
  }

  async function submitClaim(event) {
    event.preventDefault();
    if (!selectedRow || !selectedRow.LoteRendimientoID) {
      setError('Selecciona un lote proveedor antes de abrir reclamo.');
      return;
    }
    if (!claimForm.motivo.trim()) {
      setError('Captura el motivo del reclamo.');
      return;
    }
    setClaimSubmitting(true);
    setError('');
    setNotice('');
    try {
      const payload = {
        motivo: claimForm.motivo.trim(),
        descripcion: claimForm.descripcion.trim() || null,
        prioridad: claimForm.prioridad,
        evidencia: {
          origen: 'EDARSAHUB_TABLAJERIA_LOTES_PROVEEDOR',
          loteProveedor: selectedRow.LoteProveedor || null,
          loteInterno: selectedRow.LoteInterno || null,
          semaforo: selectedRow.Semaforo || null,
          impactoEconomico: selectedRow.ImpactoEconomico || null
        }
      };
      const response = await api.post('/tablajeria/lotes-proveedor/' + selectedRow.LoteRendimientoID + '/reclamos', payload);
      setNotice('Reclamo creado' + (response.data && response.data.folio_reclamo ? ': ' + response.data.folio_reclamo : '.'));
      setClaimForm({ motivo: '', descripcion: '', prioridad: 'MEDIA' });
      await loadData();
      await loadDrilldown(selectedRow);
    } catch (err) {
      setError('No fue posible crear el reclamo proveedor.');
    } finally {
      setClaimSubmitting(false);
    }
  }

  useEffect(function init() {
    loadData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div data-testid="tablajeria-lotes-proveedor" style={{ padding: 24, display: 'grid', gap: 16 }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', gap: 16, alignItems: 'flex-start' }}>
        <div>
          <h1 style={{ margin: 0 }}>Lotes proveedor</h1>
          <p style={{ margin: '6px 0 0', color: '#4b5563' }}>Rendimiento, desviaciones, impacto económico y reclamos por lote de compra.</p>
        </div>
        <button type="button" onClick={loadData} disabled={loading} style={button}>{loading ? 'Cargando...' : 'Actualizar'}</button>
      </header>

      {error ? <div role="alert" style={{ ...card, borderColor: '#fecaca', color: '#991b1b' }}>{error}</div> : null}
      {notice ? <div role="status" style={{ ...card, borderColor: '#bbf7d0', color: '#166534' }}>{notice}</div> : null}

      <section style={{ display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', gap: 12 }}>
        <div style={card}><div style={{ color: '#6b7280', fontSize: 12 }}>Lotes visibles</div><strong style={{ fontSize: 24 }}>{number(rows.length, 0)}</strong><div style={{ color: '#6b7280', fontSize: 12 }}>Total: {number(totalRows, 0)}</div></div>
        <div style={card}><div style={{ color: '#6b7280', fontSize: 12 }}>Impacto económico</div><strong style={{ fontSize: 24 }}>{money(kpis.impacto)}</strong></div>
        <div style={card}><div style={{ color: '#6b7280', fontSize: 12 }}>Alertas</div><strong style={{ fontSize: 24 }}>{number(kpis.rojos + kpis.amarillos, 0)}</strong><div style={{ color: '#6b7280', fontSize: 12 }}>Rojas: {kpis.rojos} · Amarillas: {kpis.amarillos}</div></div>
        <div style={card}><div style={{ color: '#6b7280', fontSize: 12 }}>Reclamos abiertos</div><strong style={{ fontSize: 24 }}>{number(kpis.reclamosAbiertos, 0)}</strong></div>
      </section>

      <section style={card}>
        <h2 style={{ marginTop: 0 }}>Filtros</h2>
        <div style={{ display: 'grid', gridTemplateColumns: '2fr 1.5fr 1fr auto', gap: 12, alignItems: 'end' }}>
          <label><span>Lote proveedor / interno</span><input value={filters.lote} onChange={function handle(event) { updateFilter('lote', event.target.value); }} placeholder="Buscar lote" style={input} /></label>
          <label><span>Proveedor ID</span><input value={filters.proveedor_id} onChange={function handle(event) { updateFilter('proveedor_id', event.target.value); }} placeholder="Opcional" style={input} /></label>
          <label><span>Semáforo</span><select value={filters.semaforo} onChange={function handle(event) { updateFilter('semaforo', event.target.value); }} style={input}>{SEMAFOROS.map(function option(value) { return <option key={value || 'TODOS'} value={value}>{value || 'TODOS'}</option>; })}</select></label>
          <button type="button" onClick={loadData} disabled={loading} style={secondary}>Aplicar</button>
        </div>
      </section>

      <section style={card}>
        <h2 style={{ marginTop: 0 }}>Rendimientos por lote</h2>
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
            <thead><tr style={{ textAlign: 'left', borderBottom: '1px solid #e5e7eb' }}><th style={{ padding: 8 }}>Lote</th><th style={{ padding: 8 }}>Proveedor</th><th style={{ padding: 8 }}>Orden</th><th style={{ padding: 8 }}>Kg base</th><th style={{ padding: 8 }}>Rend. esp.</th><th style={{ padding: 8 }}>Rend. real</th><th style={{ padding: 8 }}>Desv.</th><th style={{ padding: 8 }}>Merma kg</th><th style={{ padding: 8 }}>Impacto</th><th style={{ padding: 8 }}>Semáforo</th><th style={{ padding: 8 }} /></tr></thead>
            <tbody>
              {rows.map(function rowItem(row, index) {
                const selected = selectedRow && selectedRow.LoteRendimientoID === row.LoteRendimientoID;
                return (
                  <tr key={row.LoteRendimientoID || row.LoteProveedor || index} style={{ borderBottom: '1px solid #f3f4f6', background: selected ? '#f9fafb' : '#fff' }}>
                    <td style={{ padding: 8 }}><strong>{row.LoteProveedor || row.LoteInterno || 'Sin lote'}</strong><div style={{ color: '#6b7280', fontSize: 12 }}>{date(row.FechaOperacionMexico)}</div></td>
                    <td style={{ padding: 8 }}>{row.ProveedorNombre || 'Sin proveedor'}</td>
                    <td style={{ padding: 8 }}>{row.FolioOrdenTablaje || '-'}</td>
                    <td style={{ padding: 8 }}>{number(row.CantidadBaseKg)}</td>
                    <td style={{ padding: 8 }}>{number(row.RendimientoEsperadoPorcentaje)}%</td>
                    <td style={{ padding: 8 }}>{number(row.RendimientoRealPorcentaje)}%</td>
                    <td style={{ padding: 8 }}>{number(row.DesviacionPorcentaje)}%</td>
                    <td style={{ padding: 8 }}>{number(row.MermaRealKg)}</td>
                    <td style={{ padding: 8 }}>{money(row.ImpactoEconomico)}</td>
                    <td style={{ padding: 8 }}><SemaforoBadge value={row.Semaforo} /></td>
                    <td style={{ padding: 8, textAlign: 'right' }}><button type="button" onClick={function detail() { loadDrilldown(row); }} style={secondary}>Ver detalle</button></td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        {!rows.length && !loading ? <p>Sin registros con los filtros actuales.</p> : null}
      </section>

      <section style={{ display: 'grid', gridTemplateColumns: '1.2fr 0.8fr', gap: 16 }}>
        <div style={card}>
          <h2 style={{ marginTop: 0 }}>Drilldown del lote</h2>
          {!selectedRow ? <p>Selecciona un lote para ver compra, recepción, tablajería, notificaciones y reclamos.</p> : null}
          {detailLoading ? <p>Cargando detalle...</p> : null}
          {selectedRow && !detailLoading ? (
            <div style={{ display: 'grid', gap: 12 }}>
              <div><strong>{selectedRow.LoteProveedor || selectedRow.LoteInterno || 'Sin lote'}</strong><p style={{ margin: '4px 0', color: '#4b5563' }}>{selectedRow.ProveedorNombre || 'Sin proveedor'}</p></div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', gap: 8 }}>
                <div style={{ background: '#f9fafb', borderRadius: 8, padding: 10 }}><div>OC</div><strong>{selectedRow.OrdenCompraFolio || '-'}</strong></div>
                <div style={{ background: '#f9fafb', borderRadius: 8, padding: 10 }}><div>Recepción</div><strong>{selectedRow.RecepcionFolio || '-'}</strong></div>
                <div style={{ background: '#f9fafb', borderRadius: 8, padding: 10 }}><div>Factura</div><strong>{selectedRow.FacturaFolio || '-'}</strong></div>
              </div>
              <div><h3>Notificaciones</h3>{drilldown && drilldown.notificaciones && drilldown.notificaciones.length ? <ul>{drilldown.notificaciones.map(function item(n, index) { return <li key={n.NotificacionLoteID || index}>{n.TipoNotificacion || 'Notificación'} · {n.Estatus || 'SIN_ESTATUS'}</li>; })}</ul> : <p>Sin notificaciones.</p>}</div>
              <div><h3>Reclamos del lote</h3>{drilldown && drilldown.reclamos && drilldown.reclamos.length ? <ul>{drilldown.reclamos.map(function item(r, index) { return <li key={r.ReclamoProveedorID || index}><strong>{r.FolioReclamo || 'Sin folio'}</strong> · {r.Estatus || 'SIN_ESTATUS'} · {r.Prioridad || 'SIN_PRIORIDAD'}</li>; })}</ul> : <p>Sin reclamos ligados al lote.</p>}</div>
            </div>
          ) : null}
        </div>

        <form onSubmit={submitClaim} style={card}>
          <h2 style={{ marginTop: 0 }}>Abrir reclamo proveedor</h2>
          <p style={{ color: '#4b5563' }}>Se liga al lote seleccionado y conserva evidencia básica del rendimiento.</p>
          <div style={{ display: 'grid', gap: 12 }}>
            <label><span>Motivo</span><input value={claimForm.motivo} onChange={function handle(event) { setClaimForm(function next(current) { return { ...current, motivo: event.target.value }; }); }} placeholder="Ej. Merma fuera de tolerancia" style={input} /></label>
            <label><span>Prioridad</span><select value={claimForm.prioridad} onChange={function handle(event) { setClaimForm(function next(current) { return { ...current, prioridad: event.target.value }; }); }} style={input}>{PRIORIDADES.map(function option(value) { return <option key={value} value={value}>{value}</option>; })}</select></label>
            <label><span>Descripción</span><textarea value={claimForm.descripcion} onChange={function handle(event) { setClaimForm(function next(current) { return { ...current, descripcion: event.target.value }; }); }} rows={5} placeholder="Describe hallazgo operativo o evidencia visual." style={{ ...input, resize: 'vertical' }} /></label>
            <button type="submit" disabled={claimSubmitting || !selectedRow} style={button}>{claimSubmitting ? 'Creando...' : 'Crear reclamo'}</button>
          </div>
        </form>
      </section>

      <section style={card}>
        <h2 style={{ marginTop: 0 }}>Reclamos proveedor recientes</h2>
        <ul>
          {claims.map(function claimItem(claim, index) { return <li key={claim.ReclamoProveedorID || claim.FolioReclamo || index}><strong>{claim.FolioReclamo || 'Sin folio'}</strong> · {claim.ProveedorNombre || 'Sin proveedor'} · {claim.Motivo || '-'} · {claim.Estatus || 'SIN_ESTATUS'} · {money(claim.ImpactoEconomico)}</li>; })}
        </ul>
        {!claims.length && !loading ? <p>Sin reclamos registrados.</p> : null}
      </section>
    </div>
  );
}
